from taf.ul.alarms_watchdog import Alarm

from taf.rfrl.procedures.resources.python.logger import log_input_and_output


class Alarms(object):

    def __init__(self):
        self._watchdog = None
        self._admin_alias = None
        self._setup_mode = None
        self._default_allowed_alarms = None

    @log_input_and_output
    def extend_default_allowed_alarms(self, alarms):
        """
        Adds given alarms to default allowed alarms.
        :param alarms: alarms fault IDs which will be added to default allowed alarms
        :type alarms: list(int)
        """
        if alarms:
            try:
                converted_alarms = [int(fault_id) for fault_id in alarms]
                new_allowed_alarms = [Alarm(fault_id=fault_id) for fault_id in converted_alarms]
                new_allowed_alarms = [
                    alarm for alarm in new_allowed_alarms
                    if not any(alarm.matches_exactly(default_alarm) for default_alarm in self._default_allowed_alarms)
                ]
                self._default_allowed_alarms.extend(new_allowed_alarms)
            except ValueError as e:
                e.args = ('Fault id of additional allowed alarm should be an INTEGER',)
                raise

    def start_alarms_watchdog(self, bts_config, log_dir, interval, allowed_alarms=None):
        """
        Starts watching alarms on BTS with default allowed alarms unless different allowed_alarms are set.
        :param bts_config: configuration object of BTS to which requests for active alarms will be send;
                           supported BTS configuration classes: ClassicalBts, CloudBts, RealEnb;
        :param log_dir: path to logs directory
        :type log_dir: str
        :param interval: time interval between requests to BTS for active alarms
        :type interval: Union[float, int, str]
        :type bts_config: taf.config.testline.gnb.gnb.gNB, taf.config.testline.enb.RealEnb or None
        :param allowed_alarms: list of allowed alarms, defaults to None which means that
                               default list of allowed alarms will be used
        :type allowed_alarms: list of Alarm objects from taf.ul.alarms_watchdog
        """
        if not allowed_alarms:
            allowed_alarms = self._default_allowed_alarms

        self._watchdog.watch_alarms(bts_config=bts_config, log_dir=log_dir, interval=interval,
                                    allowed_alarms=allowed_alarms)

    def check_alarms_and_stop_watchdog(self, reset_allowed_alarms=True):
        """
        Checks whether alarms watchdog detected any disallowed alarms on BTS and stops watching alarms
        afterwards. If reset_allowed_alarms is set to True then allowed alarms will be reset to default.
        :param reset_allowed_alarms: defines whether allowed alarms on gNB bts should be reset to default
        :type reset_allowed_alarms: bool
        """
        if reset_allowed_alarms:
            self._watchdog.disallow_all_alarms_except_of(alarms=self._default_allowed_alarms)

        try:
            self._watchdog.check_detected_alarms()
        finally:
            self._watchdog.stop_watching_alarms()

    def stop_watching_alarms(self):
        """
        Stops watching active alarms on BTS for disallowed alarms.
        """
        self._watchdog.stop_watching_alarms()

    @log_input_and_output
    def is_alarm_active(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None,
                        fault_signature=None, unit_path=None):
        """
        Checks whether alarm with given attributes is currently active. Raises AssertionError if not.
        At least one of alarm's attributes should be provided.
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str or None
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :param unit_path: WebM 'Configuration alarming object' column in active alarms, in AdmiApi active_alarm 'configObjectName'
                          e.g: '[ABIP_ORAN_AWHQN_CB011158] MRBTS-50438/EQM-1/APEQM-1/RMOD-1'
        :type unit_path: str or None
        :return: True if alarm is active, False otherwise
        :rtype: bool
        """
        return self._watchdog.is_alarm_active(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                              hw_path=hw_path, severity=severity, fault_signature=fault_signature, unit_path=unit_path)

    @log_input_and_output
    def get_active_alarms(self):
        """
        Gets active alarms on BTS
        :return: list of active alarms
        :rtype: list
        """
        return self._watchdog.get_active_alarms()

    @log_input_and_output
    def create_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, fault_signature=None):
        """
        Creates object of Alarm class from taf.ul.alarms_watchdog
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str or None
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :return: alarm with given parameters
        :rtype: Alarm
        """
        return self._watchdog.create_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                           hw_path=hw_path, fault_signature=fault_signature)

    @log_input_and_output
    def wait_for_active_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, fault_signature=None,
                              reason=None, timeout=90, unit_path=None):
        """
        Waits for alarm with given attributes to become active on BTS
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str or None
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :param reason: used during comparison with reason of active alarms,
               i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
               can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
               defaults to None (not used)
        :type reason: str, re.Pattern or None
        :param timeout: total time to wait for alarm to become active on BTS. Accepts Robot string time
               format i.e. 1 min 20 sec; defaults to 90 seconds.
        :type timeout: Union[str, int]
        :param unit_path: WebM 'Configuration alarming object' in active alarms, in admiApi active_alarm 'configObjectName'
                          e.g: '[ABIP_ORAN_AWHQN_CB011158] MRBTS-50438/EQM-1/APEQM-1/RMOD-1'
        :type unit_path: str
        :return: True if alarm becomes active
        :rtype: Bool
        :raises AlarmInactive: if alarm with provided attributes won't appear before timeout
        """
        return self._watchdog.wait_for_active_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                    hw_path=hw_path, fault_signature=fault_signature, reason=reason,
                                                    timeout=timeout, unit_path=unit_path)

    @log_input_and_output
    def wait_for_inactive_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None,
                                fault_signature=None, timeout=90, unit_path=None):
        """
        Waits for alarm with given attributes to become inactive on BTS
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        :param timeout: total time to wait for alarm to become active on BTS. Accepts Robot string time
               format i.e. 1 min 20 sec; defaults to 90 seconds.
        :type timeout: Union[str, int]
        :return: True if alarm becomes active
        :rtype: Bool
        :raises AlarmActive: if alarm with provided attributes won't disappear before timeout
        """
        return self._watchdog.wait_for_inactive_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                                      fault_signature=fault_signature, timeout=timeout, unit_path=unit_path)

    @log_input_and_output
    def allow_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None, severity=None,
                    fault_signature=None):
        """
        Adds new alarm into list of alarms which will be skipped during active alarms check on BTS
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        """
        self._watchdog.allow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                   unit_path=unit_path, severity=severity, fault_signature=fault_signature)

    @log_input_and_output
    def disallow_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, unit_path=None, severity=None,
                       fault_signature=None):
        """
        Removes alarm from list of alarms which will be skipped during active alarms check on BTS
        :param alarm_id: ID of alarm, e.g. 10
        :type alarm_id: str or None
        :param fault_id: ID of fault, e.g. 1800
        :type fault_id: str or None
        :param fault_name: name of fault, e.g. No Connection To Unit
        :type fault_name: str
        :param hw_path: hardware path for alarm, e.g.
               /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1
        :type hw_path: str
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param fault_signature: used during comparison with fault signature of active alarms; comparison will take
                                into account only provided attributes of fault signature; defaults to None (not used)
        :type fault_signature: dict or None
        """
        self._watchdog.disallow_alarm(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name, hw_path=hw_path,
                                      unit_path=unit_path, severity=severity, fault_signature=fault_signature)

    @log_input_and_output
    def has_detected_alarms(self):
        """
        Checks whether watch history contains any detected disallowed alarm on BTS
        :return: True if watch history contains any detected disallowed alarm, False otherwise.
        :rtype: bool
        """
        return self._watchdog.has_detected_alarms()

    def check_detected_alarms(self):
        """
        Checks whether watch history contains any detected disallowed alarm on BTS
        :raises DisallowedAlarmsDetected: when watch history contains at least one detected disallowed alarm
        """
        self._watchdog.check_detected_alarms()

    def run_when_alarm_detected(self, trigger_alarms, callback, *args, **kwargs):
        """
        Registers callback to be called when any of trigger alarms is detected and disallowed.
        :param trigger_alarms: list of alarms which, when disallowed and detected, will trigger callback execution;
                               when empty list or None is provided then any detected alarm will trigger callback;
        :type trigger_alarms: list(Alarm) or None
        :param callback: callable object (in most cases a function); it will NOT accept Robot keyword
        :type callback: Callable
        :param args: positional arguments which will be passed to callback
        :param kwargs: keyword arguments which will be passed to callback
        """
        self._watchdog.run_when_alarm_detected(trigger_alarms, callback, *args, **kwargs)

    def get_detected_alarms(self):
        """
        Returns list of alarms which were detected during active alarms check
        :return: list of currently detected alarms
        :rtype: list(Alarms)
        """
        return self._watchdog.get_detected_alarms()

    def was_alarm_detected(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None,
                           reason=None, unit_path=None, impacted_cells_count=None, fault_signature=None):
        """
        Checks whether watch history contains detected disallowed alarm with given attributes.

        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :param alarm_id: used during comparison with alarm ID of detected alarms; defaults to None (not used)
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of detected alarms; defaults to None (not used)
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of detected alarms; defaults to None (not used)
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of detected alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used)
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms,
                       i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                i.e. {'category': 'POWER_OFF',
                                      'component': '1M203838370',
                                      'date': '20230519090516.000+0300'}
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :type fault_signature: dict or None
        :return: if provided Alarm was detected during alarms watch then True will be returned, False otherwise.
        :rtype: bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        :raises InvalidAlarm: when all of provided alarm's parameters will be None
        """
        return self._watchdog.was_alarm_detected(alarm_id=alarm_id, fault_id=fault_id, fault_name=fault_name,
                                                 hw_path=hw_path, severity=severity, reason=reason, unit_path=unit_path,
                                                 impacted_cells_count=impacted_cells_count,
                                                 fault_signature=fault_signature)
